(function () {



    var doc = document.documentElement;

    var w = window;



    /*

    define four variables: curScroll, prevScroll, curDirection, prevDirection

    */



    var curScroll;

    var prevScroll = w.scrollY || doc.scrollTop;

    var curDirection = 0;

    var prevDirection = 0;



    var header = document.getElementById('Header');

    var toggled;

    var threshold = 200;



    var checkScroll = function () {

        if (!header) return;

        curScroll = w.scrollY || doc.scrollTop;

        if (curScroll > prevScroll) {

            // scrolled down

            curDirection = 2;

        } else if (curScroll < prevScroll) {

            //scrolled up

            curDirection = 1;

        }



        if (curScroll == 0) {

            header.classList.remove('StickY');

        }

        if (curDirection !== prevDirection) {

            toggled = toggleHeader();

        }



        prevScroll = curScroll;

        if (toggled) {

            prevDirection = curDirection;

        }

    };



    var toggleHeader = function () {

        if (!header) return false;



        toggled = true;

        if (curDirection === 2 && curScroll > threshold) {

            header.classList.add('Hide');

            header.classList.remove('StickY');

        } else if (curDirection === 1) {

            header.classList.remove('Hide');

            header.classList.add('StickY');



        } else {

            toggled = false;

        }

        return toggled;

    };



    window.addEventListener('scroll', checkScroll, { passive: true });

    // Initialize state on load if page is refreshed while scrolled down

    if (header && prevScroll > threshold) {

        curDirection = 2; // Assume scrolled down to hide it initially

        toggleHeader();

        prevDirection = curDirection;

    }

})();



// HEADER MENU

if (document.getElementById('MainMenu')) {

    var $hamburger = $(".hamburgerBtn");

    var $ServiceMenu = $(".ServiceMenu");

    TweenLite.set("#MainMenu .MainMenuLinks li", { autoAlpha: 0, x: -110 }),

        TweenLite.set("#MainMenu .talkTOExp", { autoAlpha: 0, y: 110 }),

        TweenLite.set("#MainMenu .socialId", { autoAlpha: 0, y: 110 }),

        TweenLite.set("#MainMenu .items", { autoAlpha: 0, x: -110 }),

        TweenLite.set("#MainMenu .hamburgerBtn", { autoAlpha: 0, x: -110 }),

        TweenLite.set("#MainMenu .Bubbles", { autoAlpha: 0 });

    var hamburgerMotion = new TimelineMax()

        // .set("body", { className: "+=MenuOpen" })
        // .add(() => document.body.classList.add("MenuOpen"))
        // .add(() => document.body.classList.remove("MenuOpen"), "+=0")

        .from("#MainMenu", 0.4, { autoAlpha: 0, x: "-100%" }, 0.2, 0.5)

        .from("#MainMenu .Brand", 0.4, { y: 40 }, 0.2, 0.5)

        .staggerTo("#MainMenu .MainMenuLinks li", 0.2, { autoAlpha: 1, x: 0, ease: Sine.easeOut }, 0.1, 0.3)

        .staggerTo(["#MainMenu .talkTOExp", "#MainMenu .socialId"], 0.3, { autoAlpha: 1, y: 0, ease: Sine.easeOut }, 0.2, 0.4)

        .staggerTo("#MainMenu .items", 0.5, { autoAlpha: 1, x: 0, ease: Sine.easeOut }, 0.3, 0.5)

        .to("#MainMenu .hamburgerBtn", 0.3, { autoAlpha: 1, x: 0 }, 1, 0.3)

        .to("#MainMenu .Bubbles", 0.4, { autoAlpha: 1 }, 1, 0.3)

        .reverse();

    $hamburger.on("click", function (e) {

        hamburgerMotion.reversed(!hamburgerMotion.reversed());

    });

    $ServiceMenu.on("click", function (e) {

        hamburgerMotion.reversed(!hamburgerMotion.reversed());

    });

    const can = document.querySelector("#MainMenu  .Bubbles> span");



    function tweenProperty(e, t, o, n) {

        var r = gsap.utils.random(1, 4, 0.2, !0),

            a = gsap.utils.random(0.2, 1.5, 0.2, !0);

        gsap.to(e, {

            [t]: gsap.utils.random(o, n),

            duration: r(),

            delay: a(),

            ease: "none",

            onComplete: tweenProperty,

            onCompleteParams: [e, t, o, n]

        });

    }

    gsap.utils.toArray("#MainMenu .Bubbles span").forEach((e) => {

        tweenProperty(e, "x", -60, 20), tweenProperty(e, "y", -80, 20), tweenProperty(e, "opacity", 0, 1);

    }),

        $(document).keyup(function (e) {

            if ($("body").hasClass("MenuOpen")) {

                27 === e.keyCode && hamburgerMotion.reversed(!hamburgerMotion.reversed());

            }

        });

    hamburgerMotion.eventCallback("onReverseComplete", () => {
        document.body.classList.remove("MenuOpen");
    });

}

